#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TreeNode {
    pub val: i64,
    pub left: Option<Box<TreeNode>>,
    pub right: Option<Box<TreeNode>>,
}

/// Helper: build a subtree `Some(Box<TreeNode>)` from a value and two children.
pub fn node(val: i64, left: Option<Box<TreeNode>>, right: Option<Box<TreeNode>>) -> Option<Box<TreeNode>> {
    Some(Box::new(TreeNode { val, left, right }))
}

/// Helper: a node with no children.
pub fn leaf(val: i64) -> Option<Box<TreeNode>> {
    node(val, None, None)
}

