#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn valid() {
        assert!(is_bst(&node(5, node(3, leaf(1), leaf(4)), node(8, leaf(6), leaf(9)))));
    }

    #[test]
    fn deep_violation() {
        assert!(!is_bst(&node(5, leaf(3), node(8, leaf(4), leaf(9)))));
    }

    #[test]
    fn empty_and_single() {
        assert!(is_bst(&None));
        assert!(is_bst(&leaf(42)));
    }

    #[test]
    fn duplicates_invalid() {
        assert!(!is_bst(&node(2, leaf(2), None)));
        assert!(!is_bst(&node(2, None, leaf(2))));
    }

    #[test]
    fn negative_and_extreme_values() {
        assert!(is_bst(&node(0, leaf(-(1i64 << 40)), leaf(1i64 << 40))));
        assert!(is_bst(&node(0, leaf(i64::MIN), leaf(i64::MAX))));
        assert!(!is_bst(&node(-1, None, leaf(-5))));
    }
}
